(n) => {
  if (n == null || Number.isNaN(n)) return '0'
  const a = Math.abs(n)
  if (a >= 1e6) return `${+(n / 1e6).toFixed(1)}M`
  if (a >= 1e5) return `${Math.round(n / 1e3)}k`
  if (a >= 1e3) return `${+(n / 1e3).toFixed(1)}k`
  return `${Math.round(n * 100) / 100}`
}

